import sys

# Simulate command line for testing
if len(sys.argv) < 4:
    sys.argv = ['cli_scanner.py', '192.168.1.1', '20', '25']

if len(sys.argv) < 4:
    print("Usage: python cli_scanner.py <target> <start_port> <end_port>")
    sys.exit(1)

target = sys.argv[1]
try:
    start = int(sys.argv[2])
    end = int(sys.argv[3])
except ValueError:
    print("Ports must be integers")
    sys.exit(1)

for port in range(start, end+1):
    print(f"Scanning {target} port {port}...")
